import{_ as a,o as t,c as o,a7 as i}from"./chunks/framework.FWlv_suP.js";const f=JSON.parse('{"title":"Personix Data Collection","description":"Official data-collection information for Personix.","frontmatter":{"title":"Personix Data Collection","description":"Official data-collection information for Personix.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/personix.md","filePath":"data-collection/personix.md"}'),n={name:"data-collection/personix.md"};function r(s,e,l,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="personix-data-collection" tabindex="-1">Personix Data Collection <a class="header-anchor" href="#personix-data-collection" aria-label="Permalink to &quot;Personix Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> August 3, 2026</p><h2 id="data-stored-locally" tabindex="-1">Data stored locally <a class="header-anchor" href="#data-stored-locally" aria-label="Permalink to &quot;Data stored locally&quot;">​</a></h2><p>Personix stores text-based saved-content records, family and health references, vehicle details, notes, checklists, and settings locally in SQLite on Android or IndexedDB in a browser. The developer does not automatically receive these records.</p><h2 id="network-processing" tabindex="-1">Network processing <a class="header-anchor" href="#network-processing" aria-label="Permalink to &quot;Network processing&quot;">​</a></h2><p>Android can contact saved websites directly to retrieve preview metadata. Browser metadata fetching is optional, disabled by default, and uses <code>api.microlink.io</code> when enabled. Opening or embedding third-party content connects to the applicable content provider.</p><h2 id="device-access" tabindex="-1">Device access <a class="header-anchor" href="#device-access" aria-label="Permalink to &quot;Device access&quot;">​</a></h2><p>Personix does not access the camera or collect photo, video, or audio attachments. A system file flow is used only when you choose to import or export an encrypted backup. Optional biometric unlock is handled by Android without providing biometric templates to Personix.</p><h2 id="advertising-and-analytics" tabindex="-1">Advertising and analytics <a class="header-anchor" href="#advertising-and-analytics" aria-label="Permalink to &quot;Advertising and analytics&quot;">​</a></h2><p>Personix has no advertising, developer-operated analytics, or tracking service.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions can be sent to <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',12)])])}const m=a(n,[["render",r]]);export{f as __pageData,m as default};
